--
-- Name: listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_id uuid NOT NULL,
    user_id uuid,
    title text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    address text,
    city text,
    state text,
    country text,
    postal_code text,
    latitude numeric(10,7),
    longitude numeric(10,7),
    property_type text,
    max_guests integer DEFAULT 1 NOT NULL,
    bedrooms integer DEFAULT 0 NOT NULL,
    beds integer DEFAULT 0 NOT NULL,
    bathrooms numeric(3,1) DEFAULT 0 NOT NULL,
    amenities jsonb DEFAULT '[]'::jsonb NOT NULL,
    images jsonb DEFAULT '[]'::jsonb NOT NULL,
    thumbnails jsonb DEFAULT '[]'::jsonb NOT NULL,
    price_per_night numeric(20,4) DEFAULT 0 NOT NULL,
    cleaning_fee numeric(20,4) DEFAULT 0 NOT NULL,
    service_fee_rate numeric(5,4) DEFAULT 0.12 NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    rating numeric(3,2) DEFAULT 0 NOT NULL,
    reviews_count integer DEFAULT 0 NOT NULL,
    total_bookings integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    "updatedAt" timestamp with time zone
);


